"""Regenerate the pre-object map using the original explicit empty binding set."""
import argparse,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from tools import podunk_field as f
def build():
 model=f.Model(f.load_recipe(),object_bindings={});atlas=f.Atlases(model);paths=[model.recipe['atlas_directory']+'/atlas-%02d.t3x'%i for i in range(len(atlas.pages))];blob=f.encode_map(model,atlas,paths);assert int.from_bytes(blob[20:24],'little')==3;return blob
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();out=a.out.resolve();assert(ROOT/'build').resolve()in out.parents;out.mkdir(parents=True,exist_ok=True);blob=build();(out/'legacy.encmap').write_bytes(blob);(out/'source.json').write_text(json.dumps(dict(scope=__doc__,bytes=len(blob),sha256=hashlib.sha256(blob).hexdigest()),indent=2)+'\n',encoding='utf8');print('Legacy map regenerated by original model,',len(blob),'bytes')
